pub fn encode_timestamp(o: &Timestamp) -> Vec<u8> {
    let mut e = Enc::new(SITES);
    enc_timestamp(o, &mut e);
    e.buf
}

/// Encode into a context that is reused, so the learned widths survive and the
/// allocation is not part of what is timed. This is the shape a real host uses.
pub fn encode_into_timestamp(o: &Timestamp, e: &mut Enc) {
    e.reset();
    enc_timestamp(o, e);
}

/// After an error the value is discarded, never returned (plan rule, R-G6).
pub fn decode_timestamp(b: &[u8]) -> Result<Timestamp, i32> {
    let mut d = Dec::new(b);
    let mut out = Timestamp::default();
    dec_timestamp(&mut d, &mut out, 0);
    if d.err != 0 { Err(d.err) } else { Ok(out) }
}

